-- Every payment gets a receipt number (printed on its receipt). Generated by the database like
-- Invoice.invoiceNumber; adding the column with a volatile default fills each existing row with its
-- own value, then the unique index is built. A collision among existing rows would abort this
-- migration (10 hex characters: vanishingly unlikely), and nothing is changed if it does.

-- AlterTable
ALTER TABLE "Payment" ADD COLUMN     "receiptNumber" TEXT NOT NULL DEFAULT ('RCT-' || upper(substring(replace(gen_random_uuid()::text, '-', ''), 1, 10)));

-- CreateIndex
CREATE UNIQUE INDEX "Payment_receiptNumber_key" ON "Payment"("receiptNumber");
